// Prüft die Eingabe des Orchestrators. Eine leere query stoppt nicht (kein Stop and Error), sondern liefert den festen Wert EINGABE_FEHLT,
// damit der Orchestrator eine Antwort bekommt. fault_test = subaus simuliert den Ausfall des Spezialisten (nur Test, Fehlerfall im Test).
// zustimmung wird auf genau ja oder nein gebracht: nur ein exaktes ja (ohne Groß- und Kleinschreibung) zählt als Zustimmung, alles andere als nein.
// v08: prioritaet wird auf genau hoch oder normal gebracht: nur ein exaktes hoch (ohne Groß- und Kleinschreibung) zählt als hoch, leer oder alles andere gilt als normal.
// v09 (mechanische Sperre): Das Feld zustimmung kommt vom Modell und ist nur eine Behauptung. Der Sub bekommt deshalb die echte Nachricht der Person (person_nachricht,
// vom Hauptworkflow deterministisch gefüllt, nie vom Modell) und die vorige Antwort des Assistenten (vorige_antwort, ebenfalls deterministisch). zustimmung bleibt nur dann ja, wenn
// (a) die Nachricht ein Ticket oder eine Vormerkung ausdrücklich verlangt (Wunsch- oder Aufforderungswort dabei, keine Verneinung) oder
// (b) die Nachricht mit einem klaren Ja beginnt (keine Verneinung) UND die vorige Antwort eine Rückfrage zu Ticket oder Vormerkung war (Fragezeichen plus Ticket oder Vormerkung).
// v10: (a) verlangt zusaetzlich ein Handlungsverb (anlegen, erstellen, eroeffnen, vormerken, eintragen, aufnehmen, legen) und darf keine Frage- oder Statuswoerter tragen (wo, wie, ob, wann, Stand, Status, kostet, erklaeren, warum, wozu, wissen); (b) das Ja darf keine Einschraenkung tragen (aber, erst, spaeter, lieber, danach, danke, reicht, jemanden, Team) und die vorige Antwort muss ein Angebot sein (soll ich, darf ich, moechtest du, willst du, magst du), ohne erklaeren und ohne oder (Zweifachfrage).
// Grenze: eine Wortliste, keine Bedeutungserkennung. Falsch gesperrte Zustimmungen sind die sichere Richtung und bleiben erlaubt (zum Beispiel Ja auf eine Rueckfrage ohne die Woerter Ticket oder Vormerkung, Bitte ohne Ticket-Nomen, englische Saetze).
// v11: bedingte, simulierte, hypothetische und aufgeschobene Auftraege sind keine Zustimmung (sobald, falls, wenn, sofern, nachdem, bevor, spaeter, simulieren, Probe, Test, angenommen, vielleicht, eventuell, erst, noch nicht, zustimm...): im Zweifel gesperrt, der Orchestrator fragt zurueck. Gilt fuer die ausdrueckliche Bitte und fuer das Ja.
// Sonst nein, auch wenn das Modell ja meldet (zustimmung_gesperrt true). Fehlt die Nachricht, gilt nein (sichere Richtung). Eine Zustimmung, die über mehrere Nachrichten verteilt ist, sieht der Sub nicht.
const inp = $input.first().json;
const query = String(inp.query ?? '').trim().slice(0, 4000);
const sessionId = String(inp.session_id ?? '').trim();
const fault = String(inp.fault_test ?? '').trim();
const nachricht = String(inp.person_nachricht ?? '').trim().slice(0, 1500);
const vorige = String(inp.vorige_antwort ?? '').trim().slice(0, 1500);
const zustimmungRoh = String(inp.zustimmung ?? '').trim().toLowerCase() === 'ja';
const L = 'A-Za-zÄÖÜäöüß';
const wort = (alt) => new RegExp('(?<![' + L + '])(?:' + alt + ')(?![' + L + '])', 'i');
const verneinung = wort('nein|nicht|nie|niemals|kein\\w*|ohne|nichts').test(nachricht);
const nennt = /(ticket\w*|vormerk\w*)/i.test(nachricht);
const frageWort = wort('wo|wie|ob|wann|stand|status|kostet|kosten|erkl[a-zäöüß]*|bedeut[a-zäöüß]*|warum|wozu|wissen|was ist');
const verb = wort('anleg\\w*|erstell\\w*|eröffn\\w*|vormerk\\w*|vorgemerkt|eintrag\\w*|aufnehm\\w*|leg\\w*');
const verlangt = wort('bitte|leg\\w*|erstell\\w*|anleg\\w*|eröffn\\w*|mach\\w*|eintrag\\w*|aufnehm\\w*|vormerk\\w*|vorgemerkt|möchte|moechte|will|wünsche|brauche').test(nachricht) && !/(erkl[a-zäöüß]*|bedeut[a-zäöüß]*|was ist|wie funktioniert|wozu|warum)/i.test(nachricht);
const bedingung = wort('sobald|falls|wenn|sofern|nachdem|bevor|später|spaeter|simul[a-zäöüß]*|probe[a-zäöüß]*|test[a-zäöüß]*|trocken[a-zäöüß]*|angenommen|hypothetisch[a-zäöüß]*|vielleicht|eventuell|ggf|gegebenenfalls|erst|noch nicht|zustimm[a-zäöüß]*|zugestimmt|einverstanden|vorschau|würde|wuerde|könnte|koennte|nur prüfen|nur pruefen|prüf[a-zäöüß]*|pruef[a-zäöüß]*').test(nachricht);
const ausdruecklich = nennt && verlangt && verb.test(nachricht) && !frageWort.test(nachricht) && !verneinung && !bedingung;
const jaAnfang = /^\s*(ja|jap|jo|gern|gerne|sehr gern|ok|okay|klar|einverstanden|passt|genau|yes|mach das|machen sie das)(?![A-Za-zÄÖÜäöüß])/i.test(nachricht);
const rueckfrage = /\?/.test(vorige) && /(ticket|vormerk)/i.test(vorige) && /(soll ich|darf ich|möchtest du|moechtest du|willst du|magst du)/i.test(vorige) && !/erkl/i.test(vorige) && !wort('oder').test(vorige);
const einschraenkung = wort('aber|erst|später|spaeter|lieber|danach|sondern|rücksprache|ruecksprache|danke|reicht|doch|jemanden|team').test(nachricht);
const jaAufRueckfrage = jaAnfang && !verneinung && !einschraenkung && !bedingung && rueckfrage;
const erlaubt = ausdruecklich || jaAufRueckfrage;
const zustimmung = (zustimmungRoh && erlaubt) ? 'ja' : 'nein';
const zustimmungGesperrt = zustimmungRoh && !erlaubt;
const prioritaet = String(inp.prioritaet ?? '').trim().toLowerCase() === 'hoch' ? 'hoch' : 'normal';
let fehler = '';
if (fault === 'subaus') fehler = 'SPEZIALIST_AUSGEFALLEN';
else if (!query) fehler = 'EINGABE_FEHLT';
return [{ json: { valid: fehler === '', fehler, query, session_id: sessionId, zustimmung, zustimmung_modell: zustimmungRoh ? 'ja' : 'nein', zustimmung_gesperrt: zustimmungGesperrt, prioritaet, fault_test: fault } }];

// Bündelt die Rückgabe des Agenten für den Orchestrator. werkzeuge trägt jeden Werkzeugaufruf mit Name und Rückgabe,
// damit der Hauptworkflow die Schritte im Adapter auspacken und Werkzeugwahl messen sie wie in v06 bewerten kann.
// v09: Die 2 Werkzeuge liegen am MCP-Server, der Client-Knoten K1_MCP_Aktion reicht sie an den Agenten. Gemessen (Ausführung 2107 am Auskunfts-Agenten, 2116 hier): im Protokoll heißt ein Werkzeug
// <Clientname>_<Werkzeugname> mit EINEM Unterstrich, und die Rückgabe ist mehrfach verpackt: [{response:[{type:text,text:"[{data:...}]"}]}].
// Der Hauptworkflow vergleicht exakte Namen (Teamvormerkung, Eilmeldung_ans_Team) und liest die Rückgabe als Text oder JSON in der Form von v08. Deshalb gibt dieser Knoten
// das Namensende weiter und packt die Rückgabe bis zum eigentlichen Inhalt aus. Vorsicht: das Feld response der Mailantwort (SMTP-Text) ist KEIN Verpackungsfeld, dort bleibt das Objekt mit accepted und rejected erhalten (Fehler in Ausführung 2116, behoben).
const NAMEN = ['Teamvormerkung', 'Eilmeldung_ans_Team'];
const nameEnde = (t) => { const s = String(t); return NAMEN.find(n => s === n || s.endsWith('_' + n)) || s; };
const auspacken = (v, tiefe = 0) => {
  if (tiefe > 8) return typeof v === 'string' ? v : JSON.stringify(v);
  if (typeof v === 'string') { let p; try { p = JSON.parse(v); } catch (e) { return v; } return (p !== null && typeof p === 'object') ? auspacken(p, tiefe + 1) : v; }
  if (Array.isArray(v)) {
    if (v.length > 0 && v.every(x => x && typeof x === 'object' && x.type === 'text' && typeof x.text === 'string')) return v.map(x => auspacken(x.text, tiefe + 1)).join('\n');
    if (v.length === 1) return auspacken(v[0], tiefe + 1);
    return JSON.stringify(v);
  }
  if (v && typeof v === 'object') {
    if (v.response !== null && typeof v.response === 'object') return auspacken(v.response, tiefe + 1);
    if (typeof v.data === 'string' && v.status === undefined) return auspacken(v.data, tiefe + 1);
    if (typeof v.pageContent === 'string') return v.pageContent;
    return JSON.stringify(v);
  }
  return String(v ?? '');
};
const it = $input.first().json;
const steps = Array.isArray(it.intermediateSteps) ? it.intermediateSteps : [];
const werkzeuge = steps.filter(s => s && s.action && s.action.tool).map(s => ({ tool: nameEnde(s.action.tool), observation: auspacken(s.observation).slice(0, 4000) }));
return [{ json: { status: 'ok', spezialist: 'Aktions_Agent', antwort: String(it.output ?? '').trim(), werkzeuge, fehler_text: '' } }];

// Fehlerweg des Agenten (v09, Werkzeuge über den MCP-Client K1_MCP_Aktion).
// Gemessen am 04.11.2026: Der Fehlerausgang des Agenten trägt keine intermediateSteps, und der Kontext des Client-Knotens ist LEER (Ausführung 2113: context {} nach einer gesendeten Eilmeldung).
// Die Rückgaben der Werkzeuge (Ticketnummer, accepted) sind im Fehlerweg deshalb nicht mehr lesbar. In v08 las dieser Knoten sie aus context.response.body der HTTP-Werkzeuge.
// Lesbar bleibt isExecuted: true, wenn der Client ein Werkzeug aufgerufen hat (2113 true), false, wenn der Agent vorher scheiterte (2115 false, beide Modelle ungültig).
// Folge, bewusst vorsichtig (nicht bestätigt heißt nicht, dass nichts geschah): lief ein Werkzeug, bleibt aktion_stand werkzeug_lief, der Hauptworkflow hängt dann den Hinweis an,
// dass ein Teil schon ausgeführt sein kann. Der Zusatz mit Ticketnummer oder Eilmeldung bestätigt (TEILWEISE) entfällt im Fehlerweg; im Normalweg bleibt der Beleg aus intermediateSteps.
const item = $input.first().json;
let lief = false; try { lief = $('K1_MCP_Aktion').isExecuted === true; } catch (e) { lief = false; }
return [{ json: { ...item, antwort: 'SPEZIALIST_AUSGEFALLEN', werkzeuge: [], aktion_stand: lief ? 'werkzeug_lief' : 'unbekannt', client_lief: lief } }];
